package agentusage

import (
	"bytes"
	"fmt"
	"reflect"
	"testing"
)

// DEVDESK-47 step 1: per-model tokens (Agent.ByModel) and the 1 h cache-write
// split (ModelUsage.CacheWrite1h). Tokens itself is not touched.

// splitLine builds a transcript line whose usage carries cache_creation with
// the given raw ephemeral_1h value ("" omits the cache_creation object).
// total is cache_creation_input_tokens.
func splitLine(id, model string, in, out, total int64, raw1h string) []byte {
	cc := ""
	if raw1h != "" {
		cc = fmt.Sprintf(`,"cache_creation":{"ephemeral_5m_input_tokens":0,"ephemeral_1h_input_tokens":%s}`, raw1h)
	}
	idKey := ""
	if id != "" {
		idKey = `"id":"` + id + `",`
	}
	return []byte(fmt.Sprintf(`{"version":"2.1.302","message":{%s"model":"%s","stop_reason":"end_turn","usage":{"input_tokens":%d,"output_tokens":%d,"cache_read_input_tokens":0,"cache_creation_input_tokens":%d%s}}}`,
		idKey, model, in, out, total, cc))
}

func TestDecodeLineCacheWriteSplit(t *testing.T) {
	tests := []struct {
		name   string
		raw1h  string
		total  int64
		want1h int64
	}{
		{"5m and 1h split", "200", 300, 200},
		{"no cache_creation object", "", 300, 0},
		{"1h larger than the total is clamped", "500", 300, 300},
		{"1h equals the total", "300", 300, 300},
		{"negative 1h is 0", "-1", 300, 0},
		{"fractional 1h is 0", "1.5", 300, 0},
		{"string 1h is 0", `"x"`, 300, 0},
		{"null 1h is 0", "null", 300, 0},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			rec, kind := decodeLine(splitLine("m1", "m", 1, 2, tt.total, tt.raw1h))
			if kind != kindUsage {
				t.Fatalf("kind = %v, want kindUsage (a bad split must not make the line unreadable)", kind)
			}
			if want := (Tokens{Input: 1, Output: 2, CacheWrite: tt.total}); rec.Usage != want {
				t.Errorf("Usage = %+v, want %+v (token totals must not move)", rec.Usage, want)
			}
			if rec.CacheWrite1h != tt.want1h {
				t.Errorf("CacheWrite1h = %d, want %d", rec.CacheWrite1h, tt.want1h)
			}
		})
	}
}

func TestModelUsageCacheWrite5m(t *testing.T) {
	m := ModelUsage{Model: "m", Tokens: Tokens{CacheWrite: 300}, CacheWrite1h: 200}
	if got := m.CacheWrite5m(); got != 100 {
		t.Errorf("CacheWrite5m = %d, want 100", got)
	}
}

func byModelOf(t *testing.T, agents []Agent, idx int) []ModelUsage {
	t.Helper()
	return agents[idx].ByModel
}

func TestAggregateByModel(t *testing.T) {
	type line struct {
		id, model string
		in, out   int64
		cw        int64
		raw1h     string
	}
	tests := []struct {
		name  string
		lines []line
		want  []ModelUsage
	}{
		{"two models, first-appearance order",
			[]line{
				{"m-a", "model-a", 1, 2, 300, "200"},
				{"m-b", "model-b", 10, 20, 50, ""},
				{"m-c", "model-a", 3, 4, 100, "100"},
			},
			[]ModelUsage{
				{Model: "model-a", Tokens: Tokens{Input: 4, Output: 6, CacheWrite: 400}, CacheWrite1h: 300},
				{Model: "model-b", Tokens: Tokens{Input: 10, Output: 20, CacheWrite: 50}},
			}},
		{"no model goes to a last bucket",
			[]line{
				{"m-a", "", 5, 5, 10, ""},
				{"m-b", "model-b", 1, 1, 0, ""},
			},
			[]ModelUsage{
				{Model: "model-b", Tokens: Tokens{Input: 1, Output: 1}},
				{Model: "", Tokens: Tokens{Input: 5, Output: 5, CacheWrite: 10}},
			}},
		{"1h clamped to the line's total",
			[]line{{"m-a", "model-a", 0, 0, 300, "500"}},
			[]ModelUsage{{Model: "model-a", Tokens: Tokens{CacheWrite: 300}, CacheWrite1h: 300}}},
		{"last line of a message wins with its split",
			[]line{
				{"m-a", "model-a", 1, 1, 300, ""},
				{"m-a", "model-a", 1, 9, 300, "200"},
			},
			[]ModelUsage{{Model: "model-a", Tokens: Tokens{Input: 1, Output: 9, CacheWrite: 300}, CacheWrite1h: 200}}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			a := newTestAgg([]Agent{{ID: "main", Main: true}})
			var off int64
			for _, l := range tt.lines {
				a.addLine(0, "p.jsonl", off, splitLine(l.id, l.model, l.in, l.out, l.cw, l.raw1h))
				off += 1000
			}
			ag := a.finish()[0]
			got := byModelOf(t, []Agent{ag}, 0)
			if !reflect.DeepEqual(got, tt.want) {
				t.Errorf("ByModel = %+v\nwant      %+v", got, tt.want)
			}
			assertByModelSumsToTokens(t, ag)
		})
	}
}

func assertByModelSumsToTokens(t *testing.T, ag Agent) {
	t.Helper()
	var sum Tokens
	for _, m := range ag.ByModel {
		sum = sum.Add(m.Tokens)
		if m.CacheWrite1h < 0 || m.CacheWrite1h > m.Tokens.CacheWrite {
			t.Errorf("model %q: CacheWrite1h %d outside [0, %d]", m.Model, m.CacheWrite1h, m.Tokens.CacheWrite)
		}
	}
	if sum != ag.Tokens {
		t.Errorf("sum of ByModel = %+v, Agent.Tokens = %+v", sum, ag.Tokens)
	}
}

func TestAggregateByModelEachAgentApart(t *testing.T) {
	a := twoAgents()
	a.addLine(0, "p.jsonl", 0, splitLine("m1", "model-a", 1, 1, 10, "4"))
	a.addLine(1, "a1.jsonl", 0, splitLine("m2", "model-b", 2, 2, 20, "20"))
	agents := a.finish()
	if got, want := agents[0].ByModel, []ModelUsage{{Model: "model-a", Tokens: Tokens{Input: 1, Output: 1, CacheWrite: 10}, CacheWrite1h: 4}}; !reflect.DeepEqual(got, want) {
		t.Errorf("main ByModel = %+v, want %+v", got, want)
	}
	if got, want := agents[1].ByModel, []ModelUsage{{Model: "model-b", Tokens: Tokens{Input: 2, Output: 2, CacheWrite: 20}, CacheWrite1h: 20}}; !reflect.DeepEqual(got, want) {
		t.Errorf("sub-agent ByModel = %+v, want %+v", got, want)
	}
}

func TestAggregateByModelSyntheticExcluded(t *testing.T) {
	a := newTestAgg([]Agent{{ID: "main", Main: true}})
	a.addLine(0, "p.jsonl", 0, splitLine("m1", "model-a", 1, 1, 0, ""))
	a.addLine(0, "p.jsonl", 10, splitLine("m2", "<synthetic>", 0, 0, 0, ""))
	ag := a.finish()[0]
	if len(ag.ByModel) != 1 || ag.ByModel[0].Model != "model-a" {
		t.Errorf("ByModel = %+v, want only model-a", ag.ByModel)
	}
	assertByModelSumsToTokens(t, ag)
}

// Past maxNoIDEntries the table spills the oldest id-less entries into
// totals; the per-model figures must spill with them.
func TestAggregateByModelSurvivesSpill(t *testing.T) {
	const n = maxNoIDEntries + 5000
	a := newTestAgg([]Agent{{ID: "main", Main: true}})
	models := []string{"model-a", "model-b"}
	for i := 0; i < n; i++ {
		raw := ""
		if i%3 == 0 {
			raw = "1"
		}
		a.addLine(0, "p.jsonl", int64(i)*1000, splitLine("", models[i%2], 1, 2, 3, raw))
	}
	ag := a.finish()[0]
	if want := (Tokens{Input: n, Output: 2 * n, CacheWrite: 3 * n}); ag.Tokens != want {
		t.Fatalf("Tokens = %+v, want %+v", ag.Tokens, want)
	}
	if len(ag.ByModel) != 2 {
		t.Fatalf("ByModel = %+v, want 2 entries", ag.ByModel)
	}
	assertByModelSumsToTokens(t, ag)
	var one int64
	for _, m := range ag.ByModel {
		one += m.CacheWrite1h
	}
	if want := int64((n + 2) / 3); one != want {
		t.Errorf("total CacheWrite1h = %d, want %d", one, want)
	}
}

// The oracle: ReadDelta/Apply over chunked appends equals ParseSession, now
// including ByModel and the split.
func TestReadDeltaByModelMatchesParse(t *testing.T) {
	var parent, sub bytes.Buffer
	for i, l := range [][]byte{
		splitLine("m1", "model-a", 1, 1, 300, "200"),
		splitLine("m2", "model-b", 2, 2, 50, ""),
		splitLine("m3", "", 3, 3, 7, "9"),
		splitLine("m1", "model-a", 1, 5, 300, "250"), // same message, later line
		splitLine("", "model-b", 4, 4, 10, "10"),
	} {
		parent.Write(l)
		parent.WriteByte('\n')
		if i%2 == 0 {
			sub.Write(splitLine(fmt.Sprintf("s%d", i), "model-c", 1, 1, 4, "1"))
			sub.WriteByte('\n')
		}
	}
	for _, size := range []int{1, 7, 64, 1 << 20} {
		t.Run(fmt.Sprintf("chunk %d", size), func(t *testing.T) {
			s := newSess(t)
			s.put(s.parent(), nil)
			s.putMeta("a1", metaFinished, 0)
			s.put(s.sub("a1"), nil)
			a := NewAggregate(s.parent())
			readApply(t, a)
			pd, sd := parent.Bytes(), sub.Bytes()
			for po, so := 0, 0; po < len(pd) || so < len(sd); {
				if po < len(pd) {
					e := min(po+size, len(pd))
					s.add(s.parent(), pd[po:e])
					po = e
				}
				if so < len(sd) {
					e := min(so+size, len(sd))
					s.add(s.sub("a1"), sd[so:e])
					so = e
				}
				readApply(t, a)
				assertMatchesParse(t, a, s)
			}
			u := a.Usage()
			if len(u.Agents[0].ByModel) != 3 {
				t.Errorf("main ByModel = %+v, want 3 entries (model-a, model-b, \"\")", u.Agents[0].ByModel)
			}
			for _, ag := range u.Agents {
				assertByModelSumsToTokens(t, ag)
			}
		})
	}
}
package agentusage

import (
	"encoding/json"
	"errors"
	"strconv"
	"time"
)

// lineKind classifies one transcript line.
type lineKind int

const (
	kindUsage      lineKind = iota // message.usage present: counts
	kindNoUsage                    // message with an id, but no usage object
	kindIgnored                    // valid JSON without a message, or a message with neither id, model nor usage
	kindUnreadable                 // not JSON, truncated, or bad counters
	kindSynthetic                  // model "<synthetic>": never counts
)

// record is what decodeLine extracts from a line; only these fields are read.
type record struct {
	MessageID string
	Model     string
	Version   string
	Usage     Tokens
	StopNull  bool
	At        time.Time // root timestamp in UTC; zero if absent or not a date
	Tools     []toolRef // tool_use blocks of a non-synthetic assistant line
}

// toolRef is one tool_use block of an assistant line.
type toolRef struct {
	id  string // tool_use id; "" if absent or not a string
	abi int    // the line's apiBlockIndex; -1 when absent
	idx int    // position of the block in message.content
}

// wireBlock keeps a content block's type and id only: nothing else of a block
// (text, tool input, tool output) is ever declared, so none is kept.
type wireBlock struct{ Type, ID string }

// toolUseType is the content block type of a tool call.
const toolUseType = "tool_use"

// blockAt is a tool_use block with its position in message.content.
type blockAt struct {
	idx int
	wireBlock
}

// wireBlocks decodes message.content keeping the tool_use blocks only, as
// type and id: no text, tool input or tool output is retained. Content of
// another shape, and elements of another shape, yield no block and no error,
// so a malformed content costs the tool count of its line and nothing else.
type wireBlocks []blockAt

// UnmarshalJSON implements json.Unmarshaler.
func (bs *wireBlocks) UnmarshalJSON(data []byte) error {
	*bs = nil
	// Unmarshal into a slice rather than streaming through a json.Decoder: the
	// decoder copies every element, tool input included, which is several
	// times slower and allocates a multiple of the line's size.
	// encoding/json keeps an empty slot for an element of the wrong type and
	// reports an UnmarshalTypeError at the end, so positions are preserved
	// (a numeric id leaves Type set); any other error, a syntax error say,
	// ends the scan without keeping a partial result.
	var raw []wireBlock
	if err := json.Unmarshal(data, &raw); err != nil {
		var te *json.UnmarshalTypeError
		if !errors.As(err, &te) {
			return nil
		}
	}
	for i, b := range raw {
		if b.Type == toolUseType {
			*bs = append(*bs, blockAt{idx: i, wireBlock: b})
		}
	}
	return nil
}

// assistantType is the root type of the lines whose tool_use blocks count.
const assistantType = "assistant"

// syntheticModel is the model name of locally generated, never-billed turns.
const syntheticModel = "<synthetic>"

// wireLine mirrors the only keys read from a transcript line. Content,
// tools and descriptions are deliberately not declared, so encoding/json
// skips them without keeping them. Of the root, only the type, the timestamp,
// apiBlockIndex and the version are read, besides the message; of
// message.content, only the type and id of tool_use blocks (wireBlocks).
type wireLine struct {
	Type          json.RawMessage `json:"type"`
	Timestamp     json.RawMessage `json:"timestamp"`
	APIBlockIndex json.RawMessage `json:"apiBlockIndex"`
	Version       json.RawMessage `json:"version"`
	Message       *wireMessage    `json:"message"`
}

type wireMessage struct {
	ID         string          `json:"id"`
	Model      json.RawMessage `json:"model"`
	StopReason json.RawMessage `json:"stop_reason"`
	Content    wireBlocks      `json:"content"`
	Usage      *wireUsage      `json:"usage"`
}

// wireUsage keeps counters raw so a negative, fractional or non-numeric
// value can be told apart from an absent one.
type wireUsage struct {
	Input      json.RawMessage `json:"input_tokens"`
	Output     json.RawMessage `json:"output_tokens"`
	CacheRead  json.RawMessage `json:"cache_read_input_tokens"`
	CacheWrite json.RawMessage `json:"cache_creation_input_tokens"`
}

// decodeLine extracts the usage fields of one transcript line. A message
// without usage counts as kindNoUsage only if it has an id or a model (an
// assistant turn whose usage went missing or was renamed). It never
// reports a decoder error: those can quote line content, so a bad line is
// just kindUnreadable.
func decodeLine(b []byte) (record, lineKind) {
	var w wireLine
	if err := json.Unmarshal(b, &w); err != nil {
		return record{}, kindUnreadable
	}
	m := w.Message
	at := parseTimestamp(w.Timestamp)
	if m == nil {
		return record{Version: sanitizeLabel(optString(w.Version)), At: at}, kindIgnored
	}
	rec := record{
		MessageID: m.ID,
		Model:     sanitizeLabel(optString(m.Model)),
		Version:   sanitizeLabel(optString(w.Version)),
		StopNull:  isNullOrAbsent(m.StopReason),
		At:        at,
	}
	if rec.Model != syntheticModel && optString(w.Type) == assistantType {
		rec.Tools = toolRefs(m.Content, parseBlockIndex(w.APIBlockIndex))
	}
	switch {
	case rec.Model == syntheticModel:
		return rec, kindSynthetic
	case m.Usage == nil && m.ID == "" && rec.Model == "":
		// User and tool-result lines carry a message without id, usage or model.
		return rec, kindIgnored
	case m.Usage == nil:
		return rec, kindNoUsage
	}
	tokens, ok := m.Usage.tokens()
	if !ok {
		return record{}, kindUnreadable
	}
	rec.Usage = tokens
	return rec, kindUsage
}

// tokens converts the raw counters; ok is false if any is not a
// non-negative integer.
func (u *wireUsage) tokens() (Tokens, bool) {
	var t Tokens
	for _, c := range []struct {
		raw json.RawMessage
		dst *int64
	}{{u.Input, &t.Input}, {u.Output, &t.Output}, {u.CacheRead, &t.CacheRead}, {u.CacheWrite, &t.CacheWrite}} {
		n, ok := parseCounter(c.raw)
		if !ok {
			return Tokens{}, false
		}
		*c.dst = n
	}
	return t, true
}

// parseCounter reads one counter; absent or null is 0.
func parseCounter(raw json.RawMessage) (int64, bool) {
	if len(raw) == 0 || string(raw) == "null" {
		return 0, true
	}
	n, err := strconv.ParseInt(string(raw), 10, 64)
	return n, err == nil && n >= 0
}

// optString returns the JSON string held by raw, or "" if raw is absent or
// of another type: metadata of an unexpected type must not cost the line.
func optString(raw json.RawMessage) string {
	var s string
	if len(raw) == 0 || raw[0] != '"' || json.Unmarshal(raw, &s) != nil {
		return ""
	}
	return s
}

// isNullOrAbsent reports whether raw is a missing key or a JSON null. Any
// other value, whatever its type, counts as a stop reason being set.
func isNullOrAbsent(raw json.RawMessage) bool {
	return len(raw) == 0 || string(raw) == "null"
}

// parseTimestamp reads a root timestamp as an instant in UTC; anything else
// (absent, null, not a string, not RFC 3339) is the zero time.
func parseTimestamp(raw json.RawMessage) time.Time {
	s := optString(raw)
	if s == "" {
		return time.Time{}
	}
	t, err := time.Parse(time.RFC3339Nano, s)
	if err != nil {
		return time.Time{}
	}
	return t.UTC()
}

// parseBlockIndex reads apiBlockIndex; -1 if absent or not a non-negative integer.
func parseBlockIndex(raw json.RawMessage) int {
	n, err := strconv.Atoi(string(raw))
	if err != nil || n < 0 {
		return -1
	}
	return n
}

// toolRefs lists the tool calls of a line from its decoded content blocks.
func toolRefs(blocks wireBlocks, abi int) []toolRef {
	var refs []toolRef
	for _, b := range blocks {
		refs = append(refs, toolRef{id: b.ID, abi: abi, idx: b.idx})
	}
	return refs
}
package agentusage

import "time"

// Agent is the usage of one agent of a session: the orchestrator (Main) or a
// sub-agent.
type Agent struct {
	ID              string
	Main            bool
	Type            string // sub-agent type from its meta file; "" if unknown
	Models          []string
	Tokens          Tokens
	Messages        int // distinct message ids
	PartialMessages int // messages whose last line has no stop reason
	State           State
	SpawnDepth      int
	ToolCalls       int       // distinct tool_use blocks of the agent's assistant lines
	FirstActivity   time.Time // earliest line timestamp (UTC); zero if none
	LastActivity    time.Time // latest line timestamp (UTC); zero if none
	// key is the table's identity for the agent's lines (the rank of its
	// transcript); empty means ID. finish clears it from its output.
	key string
}

// Duration is LastActivity - FirstActivity, or 0 unless both are known.
func (a Agent) Duration() time.Duration {
	if a.FirstActivity.IsZero() || a.LastActivity.IsZero() {
		return 0
	}
	return a.LastActivity.Sub(a.FirstActivity)
}

// PartialOutput reports whether some message of the agent was still being
// written (no stop reason on its last line), so its output count is a floor.
func (a Agent) PartialOutput() bool { return a.PartialMessages > 0 }

// IssueKind classifies a line that could not be counted.
type IssueKind int

const (
	IssueUnreadable IssueKind = iota // not JSON, truncated, or bad counters
	IssueOversized                   // longer than MaxLineBytes
	IssueOpenFailed                  // a sub-agent transcript could not be opened
	IssueReadError                   // reading stopped on an I/O error at Offset
)

// FileIssue locates one skipped line. File is a base name, never a path.
type FileIssue struct {
	File   string
	Offset int64
	Kind   IssueKind
}

// Diagnostics counts what parsing skipped or had to guess.
type Diagnostics struct {
	UnreadableLines     int
	OversizedLines      int
	NoUsage             int
	NoMessageID         int
	CrossFileDuplicates int
	MetaMissing         int
	MetaUnreadable      int
	TruncatedFiles      []string
	Files               []FileIssue
}

// Degraded reports whether anything was skipped or guessed.
func (d Diagnostics) Degraded() bool {
	return d.UnreadableLines > 0 || d.OversizedLines > 0 || d.NoUsage > 0 ||
		d.NoMessageID > 0 || d.CrossFileDuplicates > 0 || d.MetaMissing > 0 ||
		d.MetaUnreadable > 0 || len(d.TruncatedFiles) > 0 || len(d.Files) > 0
}

// Usage is the parsed usage of one session.
type Usage struct {
	SessionID   string
	Agents      []Agent
	Versions    []string
	Diagnostics Diagnostics
}

// Total returns the tokens of every agent.
func (u Usage) Total() Tokens {
	var t Tokens
	for _, a := range u.Agents {
		t = t.Add(a.Tokens)
	}
	return t
}
// Package agentusage reads coding-agent usage logs. It is pure stdlib and
// has no dependency on the UI.
package agentusage

import "math"

// Tokens counts the tokens of one or more agent requests.
type Tokens struct {
	Input      int64
	Output     int64
	CacheRead  int64
	CacheWrite int64
}

// Total returns the sum of the four counters, saturating at math.MaxInt64.
func (t Tokens) Total() int64 {
	return satAdd(satAdd(t.Input, t.Output), satAdd(t.CacheRead, t.CacheWrite))
}

// Add returns the field-wise sum of t and o, each field saturating at
// math.MaxInt64.
func (t Tokens) Add(o Tokens) Tokens {
	return Tokens{
		Input:      satAdd(t.Input, o.Input),
		Output:     satAdd(t.Output, o.Output),
		CacheRead:  satAdd(t.CacheRead, o.CacheRead),
		CacheWrite: satAdd(t.CacheWrite, o.CacheWrite),
	}
}

// satAdd adds two non-negative counters without wrapping.
func satAdd(a, b int64) int64 {
	if a > math.MaxInt64-b {
		return math.MaxInt64
	}
	return a + b
}

